20	/**
21	 * An HTML Form Element provides ready access to the form fields/controls that are associated with it. It also allows a
22	 * form to easily be submitted.
23	 */
24	public class FormElement extends Element {
25	    private final Elements linkedEls = new Elements();
26	    // contains form submittable elements that were linked during the parse (and due to parse rules, may no longer be a child of this form)
27	    private static final Evaluator submittable = Selector.evaluatorOf(StringUtil.join(SharedConstants.FormSubmitTags, ", "));
28	
29	    /**
30	     * Create a new, standalone form element.
31	     *
32	     * @param tag        tag of this element
33	     * @param baseUri    the base URI
34	     * @param attributes initial attributes
35	     */
36	    public FormElement(Tag tag, @Nullable String baseUri, @Nullable Attributes attributes) {
37	        super(tag, baseUri, attributes);
38	    }
39	
40	    /**
41	     * Get the list of form control elements associated with this form.
42	     * @return form controls associated with this element.
43	     */
44	    public Elements elements() {
45	        // As elements may have been added or removed from the DOM after parse, prepare a new list that unions them:
46	        Elements els = select(submittable); // current form children
47	        for (Element linkedEl : linkedEls) {
48	            if (linkedEl.ownerDocument() != null && !els.contains(linkedEl)) {
49	                els.add(linkedEl); // adds previously linked elements, that weren't previously removed from the DOM
50	            }
51	        }
52	
53	        return els;
54	    }
55	
56	    /**
57	     * Add a form control element to this form.
58	     * @param element form control to add
59	     * @return this form element, for chaining
60	     */
61	    public FormElement addElement(Element element) {
62	        linkedEls.add(element);
63	        return this;
64	    }
65	
66	    /**
67	     * Resolve the controls that submit with this form, in document order.
68	     * <p>In addition to descendant controls (and controls linked to this form at parse time), this includes controls
69	     * anywhere else in the same Document whose {@code form} attribute references this form's {@code id}, per the
70	     * HTML form-association rules. A control carrying a {@code form} attribute belongs solely to its referenced form:
71	     * a descendant with a {@code form} attribute pointing elsewhere is excluded, and an unresolvable reference (no
72	     * such id, or the target is not a form) associates it with nothing. When several forms share an id, only the
73	     * first such form in document order absorbs externally-associated controls. Computed fresh from the live DOM on
74	     * every call; the form must have a non-empty id to absorb any external controls.</p>
75	     */
76	    private Elements formControls() {
77	        Document doc = ownerDocument();
78	        if (doc == null)
79	            return elements(); // a detached form has no document to resolve external associations against
80	
81	        String id = id();
82	        // Per the HTML spec, a form attribute resolves to the first element in tree order with that id, and only
83	        // associates when that element is a form. So this form absorbs external controls solely when it itself is
84	        // that first element: a missing id, a non-form target, another form, or an earlier same-id form all fail.
85	        boolean absorbsExternals = id.length() > 0 && doc.getElementById(id) == this;
86	
87	        Set<Element> descendants = new HashSet<>(this.getAllElements());
88	        Set<Element> linked = new HashSet<>(linkedEls);
89	        Elements controls = new Elements();
90	        for (Element el : doc.getAllElements()) { // a single document-order pass merges descendants and external controls
91	            if (!el.tag().isFormSubmittable()) continue;
92	            boolean belongs;
93	            if (el.hasAttr("form")) // an explicit association decides, even for descendants (form="" resolves to nothing)
94	                belongs = absorbsExternals && el.attr("form").equals(id);
95	            else
96	                belongs = descendants.contains(el) || linked.contains(el); // implicit: descendant, or linked at parse time
97	            if (belongs) controls.add(el);
98	        }
99	        return controls;
100	    }
101	
102	    @Override
103	    protected void removeChild(Node out) {
104	        super.removeChild(out);
105	        linkedEls.remove(out);
106	    }
107	
108	    /**
109	     Prepare to submit this form. A Connection object is created with the request set up from the form values. This
110	     Connection will inherit the settings and the cookies (etc) of the connection/session used to request this Document
111	     (if any), as available in {@link Document#connection()}
112	     <p>You can then set up other options (like user-agent, timeout, cookies), then execute it.</p>
113	
114	     @return a connection prepared from the values of this form, in the same session as the one used to request it
115	     @throws IllegalArgumentException if the form's absolute action URL cannot be determined. Make sure you pass the
116	     document's base URI when parsing.
117	     */
118	    public Connection submit() {
119	        String action = hasAttr("action") ? absUrl("action") : baseUri();
120	        Validate.notEmpty(action, "Could not determine a form action URL for submit. Ensure you set a base URI when parsing.");
121	        Connection.Method method = attr("method").equalsIgnoreCase("POST") ?
122	                Connection.Method.POST : Connection.Method.GET;
123	
124	        Document owner = ownerDocument();
125	        Connection connection = owner != null? owner.connection().newRequest() : Jsoup.newSession();
126	        return connection.url(action)
127	                .data(formData())
128	                .method(method);
129	    }
130	
131	    /**
132	     * Get the data that this form submits, using the browser's <i>successful controls</i> semantics: controls are
133	     * returned in DOM order; controls without a {@code name}, disabled controls (including those inside a disabled
134	     * {@code fieldset}, excepting descendants of that fieldset's first {@code legend} child), and {@code button} /
135	     * {@code reset} / {@code submit} / {@code image} inputs are excluded;
136	     * checkboxes and radios are only included when {@code checked} (defaulting to the value {@code "on"}); a
137	     * {@code select[multiple]} submits every selected option, while a single {@code select} with no selected option
138	     * falls back to its first non-disabled option. Options that are disabled, either directly or by a disabled
139	     * {@code optgroup} ancestor, are never submitted.
140	     * <p>In addition to the form's descendant controls, controls elsewhere in the same Document that carry a
141	     * {@code form} attribute whose value is this form's {@code id} are submitted as well (matching the browser's
142	     * <a href="https://html.spec.whatwg.org/multipage/form-control-infrastructure.html#association-of-controls-and-forms">
143	     * form-associated elements</a> rules). All controls are merged in document order. A control with a {@code form}
144	     * attribute is handled solely by that explicit association, even when it is also a descendant: an unresolvable
145	     * value (no such id, the target is not a form, or an earlier form in the Document shares this id) excludes it.
146	     * Forms without an id absorb no external controls.</p>
147	     * The list is re-queried from the DOM on each call, so changes to the document are reflected. The returned list is a copy of the data, and changes to the contents of the
148	     * list will not be reflected in the DOM.
149	     * @return a list of key vals
150	     */
151	    public List<Connection.KeyVal> formData() {
152	        ArrayList<Connection.KeyVal> data = new ArrayList<>();
153	
154	        // iterate the form control elements and accumulate their values
155	        for (Element el: formControls()) {
156	            if (!el.tag().isFormSubmittable()) continue; // contents are form listable, superset of submitable
157	            if (isDisabled(el)) continue; // skip disabled form inputs
158	            String name = el.attr("name");
159	            if (name.length() == 0) continue;
160	            String type = el.attr("type");
161	
162	            if (el.nameIs("button") || type.equalsIgnoreCase("button") || type.equalsIgnoreCase("reset")
163	                || type.equalsIgnoreCase("submit") || type.equalsIgnoreCase("image")) continue; // browsers don't submit these (a submit button only if it was the clicker)
164	
165	            if (el.nameIs("select")) {
166	                Elements options = el.select("option[selected]");
167	                boolean set = false;
168	                for (Element option: options) {
169	                    if (isDisabledOption(option)) continue; // disabled options are not successful
170	                    data.add(HttpConnection.KeyVal.create(name, option.val()));
171	                    set = true;
172	                }
173	                if (!set && !el.hasAttr("multiple")) {
174	                    // a single select defaults to its first non-disabled option
175	                    for (Element option : el.select("option")) {
176	                        if (!isDisabledOption(option)) {
177	                            data.add(HttpConnection.KeyVal.create(name, option.val()));
178	                            break;
179	                        }
180	                    }
181	                }
182	            } else if ("checkbox".equalsIgnoreCase(type) || "radio".equalsIgnoreCase(type)) {
183	                // only add checkbox or radio if they have the checked attribute
184	                if (el.hasAttr("checked")) {
185	                    final String val = el.val().length() >  0 ? el.val() : "on";
186	                    data.add(HttpConnection.KeyVal.create(name, val));
187	                }
188	            } else {
189	                data.add(HttpConnection.KeyVal.create(name, el.val()));
190	            }
191	        }
192	        return data;
193	    }
194	
195	    /**
196	     * An option is disabled if it has the {@code disabled} attribute itself, or if it descends from a {@code optgroup}
197	     * that does. Evaluated from the live DOM on each call.
198	     */
199	    private static boolean isDisabledOption(Element option) {
200	        if (option.hasAttr("disabled")) return true;
201	        for (Element parent = option.parent(); parent != null && !parent.nameIs("select"); parent = parent.parent()) {
202	            if (parent.nameIs("optgroup") && parent.hasAttr("disabled"))
203	                return true;
204	        }
205	        return false;
206	    }
207	
208	    /**
209	     * A form control is disabled if it has the {@code disabled} attribute, or if it is a descendant of a
210	     * {@code fieldset} that does. Controls descending from the fieldset's first {@code legend} element child are
211	     * excepted from that fieldset's disabling (but may still be disabled by their own attribute or another
212	     * ancestor fieldset). Evaluated from the live DOM on each call.
213	     */
214	    private static boolean isDisabled(Element el) {
215	        if (el.hasAttr("disabled")) return true;
216	        for (Element parent = el.parent(); parent != null; parent = parent.parent()) {
217	            if (parent.nameIs("fieldset") && parent.hasAttr("disabled") && !inFirstLegend(parent, el))
218	                return true;
219	        }
220	        return false;
221	    }
222	
223	    /**
224	     * Tests if {@code el} descends from the first {@code legend} element child of {@code fieldset} (which must be an
225	     * ancestor of {@code el}). Only that first direct-child legend is excepted; later or nested legends are not.
226	     */
227	    private static boolean inFirstLegend(Element fieldset, Element el) {
228	        Element legend = null;
229	        for (Element child : fieldset.children()) {
230	            if (child.nameIs("legend")) {
231	                legend = child;
232	                break;
233	            }
234	        }
235	        if (legend == null) return false;
236	        for (Element parent = el.parent(); parent != null && parent != fieldset; parent = parent.parent()) {
237	            if (parent == legend) return true;
238	        }
239	        return false;
240	    }
241	
242	    @Override
243	    public FormElement clone() {
244	        return (FormElement) super.clone();
245	    }
